      const amount = lore.entries.reduce((total, entry) => total + entry.content.length, 0);
      if (size + amount > 64000) {
        task.skipped.push({ contact: candidate.name, reason: '完整人物原文超出本轮 64000 字符预算，未截断档案。' }); continue;
