      skipped: [] };
    if (['getSnapshot', 'getRecords', 'getContext', 'getCharacterLore', 'injectPrompt'].some(key => typeof options[key] !== 'function')) {
      task.skipped.push({ contact: '', reason: '人物提示读取接口未就绪，本轮继续普通世界书。' });
