    /* MONO ADV radial launcher: eight original application destinations. */
  const RADIAL_APPS = ['blazer','lime','moments','bbs','schedule','gallery','calendar','settings'];
  function placeWheel() {
    if (!SS.wheel || !SS.wheelOpen) return;
    const vp = viewport();
    const size = SS.asterisk ? Math.min(370, (vp.w - 28) / 1.12, (vp.h - 80) / 1.22) : Math.min(370, vp.w - 20, vp.h - 72);
    const cx = SS.orbPos.x + ORB_W / 2, cy = SS.orbPos.y + ORB_H / 2;
    const x = Math.max(vp.x + (SS.asterisk ? size * .06 + 12 : 10), Math.min(cx - size / 2, vp.x + vp.w - size - (SS.asterisk ? size * .06 + 12 : 10)));
    const y = Math.max(vp.y + 10, Math.min(cy - size / 2, vp.y + vp.h - size * (SS.asterisk ? 1.16 : 1) - 56));
    writePos(SS.wheel, x, y, size, size);
    writePos(SS.wheelBackdrop, vp.x, vp.y, vp.w, vp.h);
  }
  function closeWheel(restoreFocus) {
    if (!SS.wheelOpen) return;
    SS.wheelOpen = false;
    SS.wheel.classList.remove('on');
    SS.wheelBackdrop.classList.remove('on');
    SS.orb.setAttribute('aria-expanded', 'false');
    if (restoreFocus) {
      const target = SS.focusBeforeWheel && SS.focusBeforeWheel.isConnected ? SS.focusBeforeWheel : SS.orb;
      try { target.focus({preventScroll:true}); } catch (_) {}
    }
  }
  function toggleWheel(keyboard) {
    if (SS.destroyed) return;
    syncTerminalPresentation();
    if (SS.wheelOpen) { closeWheel(true); return; }
    clearOrbTip();
    SS.focusBeforeWheel = HD.activeElement;
    SS.wheelOpen = true;
    SS.wheel.classList.add('on');
    SS.wheelBackdrop.classList.add('on');
    SS.orb.setAttribute('aria-expanded', 'true');
    SS.wheel.querySelector('.mono-wheel-caption b').textContent = '选择终端应用';
    placeWheel();
    if (keyboard) SS.wheel.querySelector('.mono-sector').focus();
  }
  async function openPhoneApp(appId) {
    if (appId === 'worldbook') appId = 'calendar';
    if (appId !== 'home' && !RADIAL_APPS.includes(appId)) return;
    closeWheel(false);
    await show();
    if (!SS.visible || !SS.booted || SS.destroyed) return;
    try {
      const iw = SS.iframe && SS.iframe.contentWindow;
      if (!iw) return;
      if (typeof iw.goHome === 'function') iw.goHome();
      if (appId !== 'home' && typeof iw.openApp === 'function') iw.openApp(appId);
      iw.focus();
    } catch(e) { console.warn('[Hagun-Mono-Terminal] Navigation:', e); }
  }
  function buildWheel() {
    SS.wheelBackdrop = HD.createElement('div');
    SS.wheelBackdrop.id = 'rk-wheel-curtain';
    SS.wheelBackdrop.setAttribute('aria-hidden','true');
    HD.body.appendChild(SS.wheelBackdrop);
    SS.wheel = HD.createElement('div');
    SS.wheel.id = 'rk-wheel';
    SS.wheel.setAttribute('aria-label','破军终端操作轮盘');

    HD.body.appendChild(SS.wheel);
    SS.wheelBackdrop.addEventListener('pointerdown', () => closeWheel(true));
    renderWheelContents();
    SS.orb.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleWheel(true); }
    });
    const escape = (e) => {
      if (e.key === 'Escape') {
        if (SS.wheelOpen) { e.preventDefault(); closeWheel(true); }
        else if (SS.visible && !(e.target && /INPUT|TEXTAREA|SELECT/.test(e.target.tagName))) hide();
      }
    };
    const outside = (e) => {
