\n  overflow-wrap: anywhere;\n  appearance: none;\n}\n#scr-lime #lime-compose::placeholder { color: var(--rk-lime-muted); opacity: 1; }\n#scr-lime .rk-lime-send {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  flex: none;\n  min-width: 48px;\n  min-height: 44px;\n  padding: 8px 12px;\n  border: 0;\n  border-radius: 14px;\n  background: var(--rk-lime-accent);\n  color: var(--rk-lime-on-accent);\n  font-size: 13px;\n  font-weight: 700;\n}\n#scr-lime .rk-lime-send:hover:not(:disabled) { background: var(--rk-lime-on-accent); color: var(--rk-lime-accent); box-shadow: inset 0 0 0 1px var(--rk-lime-accent); }\n#scr-lime .rk-lime-send .ti { font-size: 19px; }\n#scr-lime .rk-lime-send-note {\n  flex: none;\n  width: 100%;\n  margin: 0;\n  padding: 0 12px 8px;\n  background: var(--rk-lime-paper);\n  color: var(--rk-lime-muted);\n  font-size: 10px;\n  line-height: 1.6;\n  text-align: center;\n  overflow-wrap: anywhere;\n}\n#scr-lime .rk-lime-composer .rk-lime-send-note { padding: 0; }\n#scr-lime .rk-lime-error {\n  flex: none;\n  margin: 0;\n  padding: 8px 12px;\n  border-top: 1px solid var(--rk-lime-line);\n  border-left: 3px solid var(--rk-lime-accent);\n  background: var(--rk-lime-soft);\n  color: var(--rk-lime-text);\n  font-size: 12px;\n  line-height: 1.6;\n  overflow-wrap: anywhere;\n}\n#scr-lime .rk-lime-notice {\n  flex: none;\n  padding: 8px 12px;\n  border-top: 1px solid var(--rk-lime-line);\n  background: var(--rk-lime-soft);\n  color: var(--rk-lime-secondary);\n  font-size: 12px;\n  line-height: 1.6;\n  overflow-wrap: anywhere;\n}\n\n@container (max-width: 360px) {\n  #scr-lime .rk-lime-header { gap: 4px; padding-inline: 6px; }\n  #scr-lime .rk-lime-profile-toggle { padding-inline: 6px; font-size: 12px; }\n  #scr-lime .rk-lime-search { padding-inline: 12px; }\n  #scr-lime .rk-lime-contact { gap: 10px; padding-inline: 12px; }\n  #scr-lime .rk-lime-timeline { padding-inline: 10px; }\n  #scr-lime .rk-lime-bubble { padding: 9px 11px; }\