ng\\\",\\\"卡爾愛蘭茲\\\":\\\"https://eriribot.github.io/rakudai-knight/resource/knightavatars/prepared/karl-erlands.png\\\",\\\"卡尔艾兰兹\\\":\\\"https://eriribot.github.io/rakudai-knight/resource/knightavatars/prepared/karl-erlands.png\\\",\\\"愛蘭茲\\\":\\\"https://eriribot.github.io/rakudai-knight/resource/knightavatars/prepared/karl-erlands.png\\\",\\\"爱兰兹\\\":\\\"https://eriribot.github.io/rakudai-knight/resource/knightavatars/prepared/karl-erlands.png\\\",\\\"大教授\\\":\\\"https://eriribot.github.io/rakudai-knight/resource/knightavatars/prepared/karl-erlands.png\\\",\\\"KarlErlands\\\":\\\"https://eriribot.github.io/rakudai-knight/resource/knightavatars/prepared/karl-erlands.png\\\",\\\"CarlErlands\\\":\\\"https://eriribot.github.io/rakudai-knight/resource/knightavatars/prepared/karl-erlands.png\\\",\\\"GrandProfessor\\\":\\\"https://eriribot.github.io/rakudai-knight/resource/knightavatars/prepared/karl-erlands.png\\\"};\\n\\u003c/script>\\n\\u003cscript>\\nfunction read(input, providedView) {\\n  const snapshot = input?.state ? input : { state: input?.stat_data || input };\\n  const stat = structuredClone(snapshot.state?.stat_data || snapshot.state || {});\\n  const source = snapshot.source ? structuredClone(snapshot.source) : null;\\n  const pending = snapshot.pending === true;\\n  const view = providedView || deriveTournament(stat);\\n  const schoolName = value => String(value || '').trim().split(/\\\\s*[/／·]\\\\s*/)[0].replace('破軍學園', '破军学园');\\n  const name = stat.系统?.主角模式 === '黑铁一辉' ? '黑铁一辉' : stat.玩家?.姓名?.trim();\\n  const school = schoolName(stat.玩家?.所属);\\n  const registry = Object.entries(stat.场景?.七星剑斗祭?.资格名册 || {});\\n  const matchesPlayer = ([, entry]) => name && school && entry.姓名 === name && schoolName(entry.学园) === school;\\n  const matches = registry.filter(matchesPlayer);\\n  // ponytail: 沿用已保存的稳定 ID；先登记资格、后加入选拔名册时用唯一姓名与学园接续。\\n  const recordedPlayer = matches.find(([id]) => id === view.playerId) || (matches.length === 1 ? matches[0] : null);\\n  const player = {\\n    id: view.playerId || recordedPlayer?.[0] || 'player',\\n    name: name || '未建档',\\n    school: stat.玩家?.所属 || '所属待确认',\\n    device: stat.玩家?.固有灵装 || '灵装待登记',\\n    rank: stat.玩家?.登记等级 || '未登记',\\n  };\\n  let qualification;\\n  const status = (key, label, reason, representatives = []) => ({ status: key, label, reason, representatives });\\n  if (pending) {\\n    qualification = status('pending', '等待 MVU 保存', '当前回复尚未保存完成，暂不确认代表资格。');\\n  } else if (snapshot.incomplete === true) {\\n    qualification = status('unconfirmed', '代表资格待确认', '当前快照尚不完整，等待已保存的资格记录。');\\n  } else {\\n    const representatives = registry.filter(([, entry]) => schoolName(entry.学园) === '破军学园' && entry.资格状态 === '已取得')\\n      .map(([id, entry]) => ({ ...view.roster.find(row => row.id === id && row.name === entry.姓名),\\n        id, name: entry.姓名, school: entry.学园, source: '资格名册', status: entry.资格状态,\\n        player: id === recordedPlayer?.[0], basis: entry.依据 }));\\n    const entry = recordedPlayer?.[1];\\n    const labels = {\\n      已取得: ['qualified', `已取得${school}代表资格`, '本局资格名册已确认取得代表资格。'],\\n      未取得: ['not-qualified', '本届未取得代表资格', '本局资格名册已记录未取得代表资格。'],\\n      已取消: ['revoked', '代表资格已取消', '本局资格名册已记录取消代表资格。'],\\n    };\\n    const [key, label, reason] = labels[entry?.资格状态] || ['unconfirmed', '代表资格待确认', '本局尚未确认代表资格；可在终端依据剧情登记，积分与背景推演不直接授予资格。'];\\n    qualification = status(key, label, entry?.依据 || reason, representatives);\\n  }\\n  const national = snapshot.nationalView || (typeof deriveNationalTournament === 'function' ? deriveNationalTournament(stat) : { exists: false, tournament: {}, participants: [], matches: [], advancement: [] });\\n  const stages = ['16强', '8强', '4强', '决赛', '冠军'];\\n  const bracket = national.matches.length || national.advancement.length ? {\\n    actual: true,\\n    players: Object.fromEntries(national.participants.map(row => [row.id, { ...row, player: row.id === (recordedPlayer?.[0] || player.id) }])),\\n    matches: national.matches.map(row => ({ id: row.id, people: row.参赛者, p1: row.参赛者[0], p2: row.参赛者[1],\\n      zone: row.分区 === '决赛区' ? 'finals' : row.分区, round: stages.indexOf(row.晋级至) + 1,\\n      label: row.轮次, winner: row.状态 === '已完成' ? row.胜者 : '', promotion: row.晋级至,\\n      date: row.日期, time: row.时间, place: row.地点, status: row.状态, basis: row.依据, from: [] })),\\n    advancement: national.advancement,\\n  } : null;\\n  return { stat, source, pending, view, player, qualification, national, bracket };\\n}\\n\\nwindow.RK_PREVIEW_MVU = { read: input => read(input, input.view) };\\n\\u003c/script>\\n\\u003cscript>\\n(() => {\\n  const embedded = window.RK_TOURNAMENT_EMBEDDED === true;\\n  const model = window.RK_PREVIEW_MVU;\\n  const bracketModel = window.RK_PREVIEW_BRACKET;\\n  const $ = selector => document.querySelector(selector);\\n  const esc = value => String(value ?? '').replace(/[&\\u003c>\\\"']/g, c => ({ '&': '&amp;', '\\u003c': '&lt;', '>': '&gt;', '\\\"': '&quot;', \\\"'\\\": '&#39;' }[c]));\\n  const normalizeName = name => String(name).normalize('NFKC').replace(/[\\\\s·・･‧•．.]/g, '');\\n  const ui = { page: 'selection', sample: 'selection', region: 'A', match: null, bracket: null, display: {} };\\n  let current;\\n  const main = $('#session-main');\\n  const dialog = $('#session-dialog');\\n  const roundLabels = ['', '首轮 · 32 → 16', '第二轮 · 16 → 8', '分区决赛 · 8 → 4', '准决赛', '决赛'];\\n\\n  function portrait(name, isPlayer = false) {\\n    const catalog = window.TOURNAMENT_ROLE_PORTRAITS || {};\\n    const canonId = Object.keys(window.TOURNAMENT_DATA.players).find(id => normalizeName(window.TOURNAMENT_DATA.players[id].name) === normalizeName(name));\\n    const src = isPlayer && ui.display.avatarUrl || catalog[normalizeName(name)] || window.TOURNAMENT_PORTRAITS[canonId];\\n    const safe = src && /^(?:assets\\\\/|data:image\\\\/(?:png|jpeg|webp|gif);base64,|https:\\\\/\\\\/)/.test(src);\\n    return `\\u003cdiv class=\\\"fighter-avatar${isPlayer ? ' session-player-avatar' : ''}\\\">${safe ? `\\u003cimg src=\\\"${esc(src)}\\\" alt=\\\"\\\" loading=\\\"lazy\\\">` : `\\u003cspan class=\\\"portrait-fallback\\\" aria-hidden=\\\"true\\\">${esc(Array.from(name || '?')[0])}\\u003c/span>`}\\u003c/div>`;\\n  }\\n  function person(id) { return ui.bracket?.players[id]; }\\n  function contenders(match) { return match.people || [match.p1, match.p2]; }\\n  function displayName(id) { return person(id)?.name || '等待上轮胜者'; }\\n  function face(id) { return portrait(displayName(id), person(id)?.player); }\\n  function openDialog(content) { $('#session-dialog-content').innerHTML = content; dialog.showModal(); }\\n  function load(snapshot, display = {}) {\\n    current = model.read(snapshot);\\n    ui.display = display;\\n    if (!embedded || display.reset) {\\n      ui.bracket = null;\\n      ui.match = null;\\n      ui.page = 'selection';\\n      dialog.close();\\n    }\\n    if (embedded || current.bracket) ui.bracket = current.bracket;\\n    if (ui.bracket && !ui.bracket.matches.some(match => match.id === ui.match)) ui.match = null;\\n    render();\\n  }\\n  function loadSample(key) {\\n    ui.sample = key;\\n    $('#snapshot-sample').value = key;\\n    const sample = model.samples[key];\\n    load(sample.state);\\n    $('#snapshot-notice').textContent = sample.description;\\n  }\\n  // 正式终端传入当前显示快照及共享选拔视图；本页不再次读取酒馆变量。\\n  window.RK_MATCH_PREVIEW = { setSnapshot(snapshot, display = {}) {\\n    ui.sample = 'imported';\\n    $('#snapshot-sample').value = '';\\n    load(snapshot, display);\\n    $('#snapshot-notice').textContent = display.sourceLabel || '已读取本局资格、赛程与赛果。';\\n  } };\\n\\n  function renderProfile() {\\n    const p = current.player, q = current.qualification, v = current.view;\\n    const row = v.roster.find(item => item.id === v.playerId);\\n    $('#session-profile').innerHTML = `\\u003csection class=\\\"session-profile\\\">${portrait(p.name, true)}\\u003cdiv class=\\\"session-identity\\\">\\u003cspan class=\\\"screen-kicker\\\">${esc(current.stat.系统?.主角模式 || '现有角色档案')}\\u003c/span>\\u003ch1>${esc(p.name || '尚未建档')}\\u003c/h1>\\u003cp>${esc(p.school || '所属待填写')}　\\u003cspan>${esc(p.rank === '未登记' ? '等级未登记' : p.rank + '级')} / ${esc(p.device || '灵装待填写')}\\u003c/span>\\u003c/p>\\u003c/div>\\u003cdiv class=\\\"session-standing\\\">\\u003cb>${esc(q.label)}\\u003c/b>\\u003cspan>${row ? `${row.wins == null ? '战绩待补' : `${row.wins}胜 ${row.losses}负`} · ${row.points == null ? '总分待确认' : `${row.points}分`}` : '等待本局选拔记录'}\\u003c/span>\\u003c/div>\\u003c/section>`;\\n  }\\n  function card(row, representative = false) {\\n    return `\\u003cbutton type=\\\"button\\\" class=\\\"session-person ${row.player ? 'is-player' : ''}\\\" data-session-person=\\\"${esc(row.id)}\\\"${representative ? ' data-session-representative=\\\"true\\\"' : ''}>${portrait(row.name, row.player)}\\u003cspan>\\u003cb>${esc(row.name)}\\u003c/b>\\u003csmall>${row.player ? '玩家 · 当前档案' : esc(row.source)}${representative ? ' · 代表' : ' · ' + esc(row.status)}\\u003c/small>\\u003c/span>\\u003cstrong>${representative ? '已确认' : row.points == null ? '待补' : row.points + '\\u003csmall>分\\u003c/small>'}\\u003c/strong>\\u003c/button>`;\\n  }\\n  function selectionMatch(match) {\\n    return `\\u003carticle class=\\\"session-ledger-row\\\">\\u003cspan>第${match.轮次}轮\\u003csmall>${esc(match.日期 || '日期待定')}\\u003c/small>\\u003c/span>\\u003cdiv>\\u003cb>${esc(match.甲方姓名)} \\u003cem>VS\\u003c/em> ${esc(match.乙方姓名)}\\u003c/b>\\u003csmall>${esc(match.地点 || '场地待定')}\\u003c/small>\\u003c/div>\\u003cstrong>${match.状态 === '已完成' ? esc(match.胜者 === match.甲方 ? match.甲方姓名 : match.乙方姓名) + ' 胜' : esc(match.状态)}\\u003c/strong>\\u003cp>${esc(match.依据)}\\u003c/p>\\u003c/article>`;\\n  }\\n  function renderSelection() {\\n    const v = current.view, q = current.qualification;\\n    const named = v.leaderboard.filter(row => row.source !== '原创' || row.player);\\n    const visible = [...named].sort((a, b) => Number(b.player) - Number(a.player));\\n    const others = v.leaderboard.filter(row => !named.includes(row));\